// Contrat d'entrée : voir automation/n8n/README.md
const body = $('Webhook TongaPass').first().json.body;
if (!body || !body.runId || !body.employee || !body.employee.username) {
  throw new Error('Charge utile TongaPass invalide');
}
return [{ json: body }];

